def transform(grid):
    bg = grid[0][0]
    h, w = len(grid), len(grid[0])
    seen = set()
    objects = []
    for r in range(h):
        for c in range(w):
            if grid[r][c] == bg or (r,c) in seen:
                continue
            stack = [(r,c)]
            seen.add((r,c))
            cells = []
            while stack:
                y,x = stack.pop()
                cells.append((y,x))
                for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
                    yy,xx=y+dy,x+dx
                    if 0 <= yy < h and 0 <= xx < w and grid[yy][xx] != bg and (yy,xx) not in seen:
                        seen.add((yy,xx)); stack.append((yy,xx))
            top=min(y for y,x in cells); left=min(x for y,x in cells)
            patch=[row[left:left+5] for row in grid[top:top+5]]
            objects.append(patch)
    result=[row[:] for row in objects[0]]
    base_color=result[0][0]
    for patch in objects[1:]:
        for r in range(5):
            for c in range(5):
                if patch[r][c] not in (bg, base_color):
                    result[r][c]=patch[r][c]
    return result

